      en: 'Full Method: For no solution (parallel lines), a₁/a₂ = b₁/b₂ ≠ c₁/c₂. Here 3 / (2k − 1) = 1 / (k − 1). Cross-multiplying: 3(k − 1) = 2k − 1 ⇒ 3k − 3 = 2k − 1 ⇒ k = 2. At k = 2, c₁/c₂ = 1 / 5 ≠ 1, so no solution holds.\n60-Second Shortcut: Plug k = 2 into the x and y ratios: 3 / (4 − 1) = 3/3 = 1 and 1 / (2 − 1) = 1/1 = 1. They match immediately!',
      pa: 'ਪੂਰਾ ਤਰੀਕਾ: ਕੋਈ ਹੱਲ ਨਾ ਹੋਣ (ਸਮਾਂਤਰ ਰੇਖਾਵਾਂ) ਲਈ a₁/a₂ = b₁/b₂ ≠ c₁/c₂ ਹੁੰਦਾ ਹੈ। ਇੱਥੇ 3 / (2k − 1) = 1 / (k − 1) ⇒ 3k − 3 = 2k − 1 ⇒ k = 2। k = 2 ਭਰਨ ਤੇ c₁/c₂ = 1/5 ≠ 1 ਹੈ।\n60-ਸਕਿੰਟ ਸ਼ਾਰਟਕੱਟ: ਵਿਕਲਪ k = 2 ਸਿੱਧਾ ਭਰੋ: 3 / (4 − 1) = 1 ਅਤੇ 1 / (2 − 1) = 1, ਦੋਵੇਂ ਅਨੁਪਾਤ ਬਰਾਬਰ ਹਨ!',
