      en: 'Full Method: Let base = x cm, then altitude = (x − 7) cm. By Pythagoras theorem: x² + (x − 7)² = 13² ⇒ 2x² − 14x + 49 = 169 ⇒ 2x² − 14x − 120 = 0 ⇒ x² − 7x − 60 = 0 ⇒ (x − 12)(x + 5) = 0. Since length x > 0, base x = 12 cm.\n60-Second Shortcut: Recall the standard Pythagorean triplet (5, 12, 13) with hypotenuse 13! Since altitude is 7 cm less than base, base = 12 cm and altitude = 5 cm.',
      pa: 'ਪੂਰਾ ਤਰੀਕਾ: ਮੰਨ ਲਓ ਆਧਾਰ = x cm, ਤਾਂ ਉਚਾਈ = (x − 7) cm। ਪਾਈਥਾਗੋਰਸ ਪ੍ਰਮੇਯ ਅਨੁਸਾਰ: x² + (x − 7)² = 13² ⇒ x² − 7x − 60 = 0 ⇒ (x − 12)(x + 5) = 0 ⇒ x = 12 cm।\n60-ਸਕਿੰਟ ਸ਼ਾਰਟਕੱਟ: ਕਰਣ 13 cm ਲਈ ਮਿਆਰੀ ਪਾਈਥਾਗੋਰਸ ਤਿੱਕੜੀ (5, 12, 13) ਯਾਦ ਰੱਖੋ! ਇੱਥੇ 12 − 5 = 7 ਹੈ, ਇਸ ਲਈ ਆਧਾਰ = 12 cm।',
