      pa: 'ਪੂਰਾ ਤਰੀਕਾ: ਇੱਥੇ ਪਹਿਲਾ ਪਦ a = 21, ਸਾਂਝਾ ਅੰਤਰ d = 18 − 21 = −3 ਅਤੇ a_n = −81 ਹੈ। ਸੂਤਰ a_n = a + (n − 1)d ਵਰਤਣ ਤੇ: −81 = 21 + (n − 1)(−3) ⇒ −102 = −3(n − 1) ⇒ n − 1 = 34 ⇒ n = 35ਵਾਂ ਪਦ।\n60-ਸਕਿੰਟ ਸ਼ਾਰਟਕੱਟ: n = ((ਅੰਤਿਮ ਪਦ − ਪਹਿਲਾ ਪਦ) / d) + 1 = (−102 / −3) + 1 = 34 + 1 = 35ਵਾਂ ਪਦ।',
