      pa: 'ਜੇਕਰ ਕਿਸੇ ਅੰਕਗਣਿਤਕ ਲੜੀ (AP) ਦੇ ਪਹਿਲੇ n ਪਦਾਂ ਦਾ ਜੋੜ S_n = 3n² + 5n ਹੈ, ਤਾਂ ਉਸ ਦਾ ਸਾਂਝਾ ਅੰਤਰ (d) ਅਤੇ 10ਵਾਂ ਪਦ (a₁₀) ਪਤਾ ਕਰੋ।',
      hi: 'यदि किसी समांतर श्रेढ़ी (AP) के प्रथम n पदों का योग S_n = 3n² + 5n द्वारा दिया जाता है, तो उसका सार्व अंतर (d) और 10वाँ पद (a₁₀) ज्ञात कीजिए।',
