      pa: 'ਪੂਰਾ ਤਰੀਕਾ: ਕੇਂਦਰਕ G = ((x₁ + x₂ + x₃)/3, (y₁ + y₂ + y₃)/3)। ਇਸ ਲਈ (3 − 7 + x₃)/3 = 2 ⇒ x₃ = 10 ਅਤੇ (−5 + 4 + y₃)/3 = −1 ⇒ y₃ = −2। C ਦੇ ਨਿਰਦੇਸ਼ਾਂਕ (10, −2) ਹਨ।\n60-ਸਕਿੰਟ ਸ਼ਾਰਟਕੱਟ: C = 3G − (A + B) = (6 − (−4), −3 − (−1)) = (10, −2)।',
