      hi: 'ΔABC में, आधार BC के समांतर खींची गई रेखा DE भुजाओं AB और AC को क्रमशः D और E पर प्रतिच्छेद करती है। यदि AD = 2.4 cm, DB = 3.6 cm और AE = 3.2 cm हो, तो पूरी भुजा AC की लंबाई ज्ञात कीजिए।',
