      pa: 'ਪੂਰਾ ਤਰੀਕਾ: ਅੰਕੜਿਆਂ ਨੂੰ ਵਧਦੇ ਕ੍ਰਮ ਵਿੱਚ ਲਿਖੋ: 12, 14, 15, 18, 21, 22, 25, 28, 30, 34। ਕਿਉਂਕਿ n = 10 (ਜਿਸਤ) ਹੈ, ਮੱਧਿਕਾ = (5ਵਾਂ ਪਦ + 6ਵਾਂ ਪਦ) / 2 = (21 + 22) / 2 = 21.5।\n60-ਸਕਿੰਟ ਸ਼ਾਰਟਕੱਟ: 4 ਸਭ ਤੋਂ ਛੋਟੀਆਂ ਅਤੇ 4 ਸਭ ਤੋਂ ਵੱਡੀਆਂ ਸੰਖਿਆਵਾਂ ਛੱਡ ਦਿਓ; ਵਿਚਕਾਰਲੀਆਂ ਦੋ (21 ਅਤੇ 22) ਦੀ ਔਸਤ = 21.5!',
