      hi: 'यदि P(E) = 0.06 है, तो "E नहीं" की प्रायिकता क्या है? साथ ही, यदि 20 बल्बों के एक समूह में 4 बल्ब खराब हैं, तो यादृच्छया निकाले गए एक बल्ब के खराब न होने की प्रायिकता क्या है?',
