    explanation: {
      en: 'Full Method: Total possible outcomes = 6 × 6 = 36. The pairs giving a sum of 8 are (2, 6), (3, 5), (4, 4), (5, 3), and (6, 2) — i.e., 5 favourable outcomes. Therefore, P(sum = 8) = 5 / 36.\n60-Second Shortcut: For any sum S between 7 and 12 on two dice, number of favourable outcomes = 13 − S. Here 13 − 8 = 5 ⇒ Probability = 5/36!',
      pa: 'ਪੂਰਾ ਤਰੀਕਾ: ਕੁੱਲ ਸੰਭਵ ਨਤੀਜੇ = 6 × 6 = 36। ਜੋੜ 8 ਬਣਾਉਣ ਵਾਲੇ ਜੋੜੇ ਹਨ: (2, 6), (3, 5), (4, 4), (5, 3), (6, 2) — ਕੁੱਲ 5 ਅਨੁਕੂਲ ਨਤੀਜੇ। ਇਸ ਲਈ ਸੰਭਾਵਨਾ = 5 / 36।\n60-ਸਕਿੰਟ ਸ਼ਾਰਟਕੱਟ: ਦੋ ਪਾਸਿਆਂ ਤੇ ਜੋੜ S (7 ਤੋਂ 12 ਤੱਕ) ਲਈ ਅਨੁਕੂਲ ਨਤੀਜੇ = 13 − S = 13 − 8 = 5 ⇒ ਸੰਭਾਵਨਾ = 5/36!',
      hi: 'पूर्ण विधि: कुल संभावित परिणाम = 6 × 6 = 36। योग 8 देने वाले युग्म हैं: (2, 6), (3, 5), (4, 4), (5, 3), (6, 2) — कुल 5 अनुकूल परिणाम। अतः प्रायिकता = 5 / 36।\n60-सेकंड शॉर्टकट: दो पासों पर योग S (7 से 12 तक) के लिए अनुकूल परिणाम = 13 − S = 13 − 8 = 5 ⇒ प्रायिकता = 5/36!',
    },
