      pa: 'ਅਬਦੁਲ ਗੱਡੀ ਰਾਹੀਂ ਸਕੂਲ ਜਾਂਦੇ ਸਮੇਂ ਆਪਣੀ ਯਾਤਰਾ ਦੀ ਔਸਤ ਚਾਲ 20 km/h ਮਾਪਦਾ ਹੈ। ਉਸੇ ਰਸਤੇ ਤੋਂ ਵਾਪਸ ਆਉਂਦੇ ਸਮੇਂ ਭੀੜ ਘੱਟ ਹੋਣ ਕਾਰਨ ਉਸ ਦੀ ਔਸਤ ਚਾਲ 30 km/h ਹੁੰਦੀ ਹੈ। ਪੂਰੀ ਯਾਤਰਾ ਲਈ ਅਬਦੁਲ ਦੀ ਔਸਤ ਚਾਲ ਕੀ ਹੈ?',
