      hi: '2 kg द्रव्यमान के एक पिस्तौल से 20 g द्रव्यमान की एक गोली 150 m/s के क्षैतिज वेग से छोड़ी जाती है। पिस्तौल के पीछे हटने के वेग (प्रतिक्षेप वेग) का परिमाण क्या होगा?',
