      pa: 'ਪੂਰਾ ਤਰੀਕਾ: ਨਿਕਟ-ਦ੍ਰਿਸ਼ਟੀ ਦੋਸ਼ (Myopia) ਵਿੱਚ ਪ੍ਰਤੀਬਿੰਬ ਰੈਟੀਨਾ ਤੋਂ ਪਹਿਲਾਂ ਬਣਦਾ ਹੈ, ਜਿਸ ਨੂੰ ਅਵਤਲ (concave) ਲੈਂਜ਼ ਨਾਲ ਠੀਕ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਇੱਥੇ ਫੋਕਸ ਦੂਰੀ f = −2 m ਹੈ, ਇਸ ਲਈ ਲੈਂਜ਼ ਦੀ ਸ਼ਕਤੀ P = 1 / f(m) = −1 / 2 = −0.5 D।\n60-ਸਕਿੰਟ ਸ਼ਾਰਟਕੱਟ: Myopia → ਅਵਤਲ ਲੈਂਜ਼ (ਰਿਣਾਤਮਕ ਸ਼ਕਤੀ) ਅਤੇ P = −1 / 2 = −0.5 D।',
