      en: 'Full Method: In Mendel’s dihybrid cross (e.g., Round Yellow RRYY × Wrinkled Green rryy), independent assortment of two traits (3 : 1) × (3 : 1) yields the F₂ phenotypic ratio 9 : 3 : 3 : 1. The forelimbs of humans, frogs, lizards, and wings of birds share the same basic bone structure/embryonic origin but perform different functions, so they are Homologous organs (whereas wings of a bird and wings of an insect are Analogous organs).\n60-Second Shortcut: Dihybrid F₂ = (3:1)² = 9:3:3:1; Same bone structure (Human arm & Bird wing) → Homologous ("Homo" = same origin).',
      pa: 'ਪੂਰਾ ਤਰੀਕਾ: ਮੈਂਡਲ ਦੇ ਦੋ-ਸੰਕਰ ਕ੍ਰਾਸ ਦੀ F₂ ਪੀੜ੍ਹੀ ਦਾ ਫੀਨੋਟਾਇਪਿਕ ਅਨੁਪਾਤ (3:1) × (3:1) = 9 : 3 : 3 : 1 ਹੁੰਦਾ ਹੈ। ਮਨੁੱਖ ਦੀਆਂ ਬਾਹਾਂ ਅਤੇ ਪੰਛੀ ਦੇ ਖੰਭਾਂ ਦੀ ਮੂਲ ਹੱਡੀਆਂ ਦੀ ਬਣਤਰ ਇੱਕੋ ਜਿਹੀ ਹੁੰਦੀ ਹੈ ਪਰ ਕੰਮ ਵੱਖ-ਵੱਖ ਹੁੰਦੇ ਹਨ, ਇਸ ਲਈ ਇਹ ਸਮਜਾਤ ਅੰਗ (Homologous organs) ਹਨ।\n60-ਸਕਿੰਟ ਸ਼ਾਰਟਕੱਟ: ਦੋ-ਸੰਕਰ F₂ = 9:3:3:1; ਇੱਕੋ ਜਿਹੀ ਮੂਲ ਬਣਤਰ → ਸਮਜਾਤ ਅੰਗ (Homologous)।',
